import{_ as n,C as r,o as s,c as d,a2 as t,b as o,w as a,a as l,E as p,a3 as h}from"./chunks/framework.CWWEQfK7.js";const v=JSON.parse('{"title":"Move the quick deployment into production","description":"Add TLS, production settings, backups, monitoring, and a clear Worker trust boundary to the release and systemd layout.","frontmatter":{"page_id":"guide-production-deployment","title":"Move the quick deployment into production","description":"Add TLS, production settings, backups, monitoring, and a clear Worker trust boundary to the release and systemd layout."},"headers":[],"relativePath":"en/guide/production-deployment.md","filePath":"en/guide/production-deployment.md","lastUpdated":1786627803000}'),c={name:"en/guide/production-deployment.md"};function u(k,e,m,g,y,b){const i=r("Mermaid");return s(),d("div",null,[e[1]||(e[1]=t('<h1 id="move-the-quick-deployment-into-production" tabindex="-1">Move the quick deployment into production <a class="header-anchor" href="#move-the-quick-deployment-into-production" aria-label="Permalink to &quot;Move the quick deployment into production&quot;">​</a></h1><p>The <a href="./quick-start">quick deployment</a> already uses release archives, PyPI, and systemd. Production keeps the same directories and services. You do not need to replace them with source installations. Before launch, add a domain and TLS, production settings, backups, monitoring, and access controls.</p><h2 id="recommended-shape" tabindex="-1">Recommended shape <a class="header-anchor" href="#recommended-shape" aria-label="Permalink to &quot;Recommended shape&quot;">​</a></h2>',3)),(s(),o(h,null,{default:a(()=>[p(i,{id:"mermaid-9",class:"ershu-mermaid",graph:"flowchart%20LR%0A%20%20User%5B%22Team%20browsers%22%5D%20--%3E%20TLS%5B%22HTTPS%20reverse%20proxy%22%5D%0A%20%20Agent%5B%22Coding%20agents%22%5D%20--%3E%20TLS%0A%20%20TLS%20--%3E%7C%22Static%20files%20at%20%2F%22%7C%20Frontend%5B%22Frontend%20dist%22%5D%0A%20%20TLS%20--%3E%7C%22%2Fapi%2F%22%7C%20API%5B%22Ershu%20API%20%3A8000%22%5D%0A%20%20TLS%20--%3E%7C%22%2Fmcp%2F%22%7C%20MCP%5B%22Ershu%20MCP%20%3A8001%22%5D%0A%20%20API%20--%3E%20PG%5B(%22PostgreSQL%22)%5D%0A%20%20MCP%20--%3E%20PG%0A%20%20Worker%5B%22Ershu%20Worker%22%5D%20--%3E%20PG%0A%20%20API%20--%3E%20Milvus%5B(%22Milvus%22)%5D%0A%20%20MCP%20--%3E%20Milvus%0A%20%20Worker%20--%3E%20Milvus%0A%20%20Worker%20--%3E%20Repos%5B%22Controlled%20repository%20storage%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t(`<p>API, MCP, and Worker may start on one trusted host or run separately. They must use the same PostgreSQL database. When vector retrieval is enabled, they must also use the same Milvus database.</p><p>The systemd files in the deployment archive target one host. For a split deployment, create equivalent services on each host while keeping the same account, configuration, and storage boundaries.</p><h2 id="_1-install-only-published-releases" tabindex="-1">1. Install only published releases <a class="header-anchor" href="#_1-install-only-published-releases" aria-label="Permalink to &quot;1. Install only published releases&quot;">​</a></h2><p>Keep every composition in its own directory:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/opt/ershu/releases/&lt;tag&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Verify the archive against <code>SHA256SUMS</code> from the same GitHub Release, then run its installer:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/systemd/install.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --uv-bin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;$(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">command</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uv)&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The installer reads the composition version from <code>versions.env</code> and installs the exact <code>ershu[all]</code> release from PyPI. Components may use different versions in later compositions. Operators still install the <code>ershu</code> version selected by the composition.</p><p><code>/opt/ershu/current</code> points to the active release. Configuration and data live outside the version directory, so switching releases does not overwrite secrets, databases, or repository caches.</p><h2 id="_2-use-production-settings" tabindex="-1">2. Use production settings <a class="header-anchor" href="#_2-use-production-settings" aria-label="Permalink to &quot;2. Use production settings&quot;">​</a></h2><p>Backend settings live in <code>/etc/ershu/.env</code>. Infrastructure settings live in <code>/etc/ershu/compose.env</code>. Review at least these values:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Production requirement</th></tr></thead><tbody><tr><td><code>ENVIRONMENT</code></td><td>Set to <code>production</code></td></tr><tr><td><code>HOST</code>, <code>MCP_HOST</code></td><td>Usually keep <code>127.0.0.1</code> and expose only the reverse proxy</td></tr><tr><td><code>SESSION_COOKIE_SECURE</code></td><td>Set to <code>true</code></td></tr><tr><td><code>CORS_ORIGINS</code></td><td>List only the real HTTPS frontend origin</td></tr><tr><td><code>PROXY_HEADERS</code></td><td>Set to <code>true</code> behind a reverse proxy</td></tr><tr><td><code>FORWARDED_ALLOW_IPS</code></td><td>Trust only the real proxy addresses</td></tr><tr><td><code>OPAQUE_SERVER_SETUP</code></td><td>Keep the value generated during the first deployment; do not regenerate it during upgrades</td></tr><tr><td><code>SECRET_KEY</code>, <code>ENCRYPTION_KEY</code>, <code>MCP_KEY_PEPPER</code></td><td>Store three different random values in a secret manager</td></tr><tr><td><code>MCP_BUILD_COMMIT</code></td><td>Set the complete 40-character commit for the deployed MCP release</td></tr><tr><td><code>MCP_ALLOWED_HOSTS</code>, <code>MCP_ALLOWED_ORIGINS</code></td><td>Allow only the real domain and HTTPS origin</td></tr><tr><td><code>ALLOW_DEV_OPEN_LOCAL_REPOSITORY_PATHS</code></td><td>Keep <code>false</code></td></tr><tr><td><code>TRUSTED_LOCAL_PATHS</code></td><td>List only repository roots that Ershu may read</td></tr><tr><td><code>REPOSITORY_STORAGE_PATH</code></td><td>Use dedicated persistent storage, by default <code>/var/lib/ershu/repositories</code></td></tr></tbody></table><p>Model API keys, repository tokens, and SSH keys belong in Ershu administration, not frontend environment variables. Whether model traffic leaves the private network depends on the model channels you create.</p><p>The active release supplies the composition version and default images, so they do not need to be copied into <code>/etc/ershu</code>. If your company uses an internal registry, put infrastructure image replacements in <code>/etc/ershu/image-overrides.env</code> and put <code>LSP_IMAGES</code> in <code>/etc/ershu/lsp-image-overrides.env</code>. These files remain active after an upgrade. Check that the internal registry has the new images before switching releases.</p><p>Restart the application services after a configuration change:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu.target</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="_3-manage-the-systemd-services" tabindex="-1">3. Manage the systemd services <a class="header-anchor" href="#_3-manage-the-systemd-services" aria-label="Permalink to &quot;3. Manage the systemd services&quot;">​</a></h2><p>The deployment archive provides these units:</p><table tabindex="0"><thead><tr><th>Unit</th><th>Purpose</th><th>Default state</th></tr></thead><tbody><tr><td><code>ershu-infrastructure.service</code></td><td>Starts and waits for PostgreSQL, Redis, Milvus, etcd, and MinIO</td><td>Starts with the application</td></tr><tr><td><code>ershu-migrate.service</code></td><td>Applies database migrations before the application starts</td><td>Starts with the application</td></tr><tr><td><code>ershu-api.service</code></td><td>Browser and HTTP API</td><td>Enabled</td></tr><tr><td><code>ershu-worker.service</code></td><td>Repository analysis</td><td>Enabled</td></tr><tr><td><code>ershu-mcp.service</code></td><td>MCP client requests</td><td>Enabled</td></tr><tr><td><code>ershu-poller.service</code></td><td>Scheduled repository checks</td><td>Disabled by default</td></tr><tr><td><code>ershu.target</code></td><td>Starts and stops API, Worker, and MCP together</td><td>Enabled</td></tr></tbody></table><p>Common commands:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu.target</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu.target</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu.target</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu.target</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-api</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-worker</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-mcp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>The units use a dedicated <code>ershu</code> account. They can write to <code>/var/lib/ershu</code>; Worker can also write to <code>/var/cache/ershu</code>. If repositories live elsewhere, update both the Ershu setting and the systemd write permissions.</p><p>API and MCP have HTTP health checks. Worker has no health port. Check its startup log and confirm that a real task moves out of <code>queued</code>.</p><h2 id="_4-add-https-and-a-production-reverse-proxy" tabindex="-1">4. Add HTTPS and a production reverse proxy <a class="header-anchor" href="#_4-add-https-and-a-production-reverse-proxy" aria-label="Permalink to &quot;4. Add HTTPS and a production reverse proxy&quot;">​</a></h2><p><code>deploy/nginx/ershu-local.conf</code> listens only on <code>127.0.0.1:8080</code> and is intended for an SSH-tunnel evaluation. Copy its three routes into your own HTTPS site for production:</p><table tabindex="0"><thead><tr><th>External path</th><th>Target</th></tr></thead><tbody><tr><td><code>/</code></td><td>Frontend static files</td></tr><tr><td><code>/api/</code></td><td><code>http://127.0.0.1:8000/api/</code></td></tr><tr><td><code>/mcp/</code></td><td><code>http://127.0.0.1:8001/mcp/</code></td></tr></tbody></table><p>The <code>/mcp/</code> route must retain its trailing slash, the <code>Authorization</code> header, and streaming responses. Pass the real Host, client address, and external HTTPS scheme to the backend. Serving the frontend and API from one domain avoids many cross-origin cookie mistakes.</p><p>Check the public domain before launch:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://ershu.example.com/api/v1/health</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://ershu.example.com/api/v1/health/dependencies</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8001/health</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>The internal MCP health check only shows that its process is running. Call <code>get_server_info</code> through the public <code>/mcp/</code> route to test proxying, authentication, and streaming.</p><h2 id="_5-back-up-and-restore" tabindex="-1">5. Back up and restore <a class="header-anchor" href="#_5-back-up-and-restore" aria-label="Permalink to &quot;5. Back up and restore&quot;">​</a></h2><p>The default data directory is <code>/var/lib/ershu/infrastructure</code>, which contains PostgreSQL, Redis, Milvus, etcd, and MinIO data. Repository copies and analysis workspaces default to <code>/var/lib/ershu/repositories</code>.</p><p>A production backup should cover:</p><ul><li>PostgreSQL, which stores users, projects, permissions, runs, and documents;</li><li>Milvus, etcd, and MinIO, unless rebuilding vector indexes from repositories is an accepted recovery plan;</li><li>backend secrets and OPAQUE material from <code>/etc/ershu</code>;</li><li>external secret systems used by repository credentials, model channels, and dependency sources;</li><li>the active <code>versions.env</code> and reverse-proxy configuration.</li></ul><p>Redis mainly holds short-lived throttling and coordination data. It is not the source of business records. Do not rely on copying live database directories. Use backup methods supported by PostgreSQL, Milvus, and the object store, then perform a restore test.</p><h2 id="_6-review-worker-and-lsp-separately" tabindex="-1">6. Review Worker and LSP separately <a class="header-anchor" href="#_6-review-worker-and-lsp-separately" aria-label="Permalink to &quot;6. Review Worker and LSP separately&quot;">​</a></h2><p>Worker reads repositories and may access private dependency sources. Restrict <code>GIT_ALLOWED_HOSTS</code> and <code>TRUSTED_LOCAL_PATHS</code>, and keep <code>REPOSITORY_STORAGE_PATH</code> in a dedicated directory.</p><p>LSP is disabled by default. When enabled, Worker invokes Docker to run short-lived language servers. Adding the <code>ershu</code> account to the Docker group gives it substantial host privileges. Confirm that:</p><ul><li>image tags come from <code>versions.env</code>, with image digests used where stronger pinning is required;</li><li>Docker can see the same absolute repository paths as Worker;</li><li>CPU, memory, process, session, and timeout limits fit the host;</li><li>only languages used by the project are enabled;</li><li>dependency sources, caches, and CA bundles have been reviewed.</li></ul><p>Use a separate Worker host or a controlled container runtime when the host Docker socket grants too much access.</p><h2 id="_7-production-acceptance-check" tabindex="-1">7. Production acceptance check <a class="header-anchor" href="#_7-production-acceptance-check" aria-label="Permalink to &quot;7. Production acceptance check&quot;">​</a></h2><p>Complete a real workflow before launch:</p><ol><li>Create an administrator and sign in over HTTPS.</li><li>Test the language-model and embedding channels.</li><li>Add a private test repository and verify its credential.</li><li>Run a full-project analysis and confirm that Worker advances the task.</li><li>Open a Wiki citation and confirm its repository and commit.</li><li>Check keyword and semantic search separately.</li><li>Create a project-scoped MCP key, call <code>get_server_info</code> from an external client, and read one project.</li><li>Restart API, Worker, and MCP, then confirm that services and task state recover.</li><li>Complete a backup and restore exercise.</li></ol><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><p>Download and verify the new deployment archive, then extract it to a new release directory. Replace the tag below with the new release and run:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NEW_TAG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">v1.0.1-20260813</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu.target</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/opt/ershu/releases/\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NEW_TAG</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/systemd/install.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --uv-bin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;$(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">command</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uv)&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu.target</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>The installer installs the new composition&#39;s <code>ershu[all]</code>, stops the old infrastructure, updates the systemd units, and switches <code>/opt/ershu/current</code>. It updates only the composition version in <code>/etc/ershu/.env</code>, leaving existing secrets and deployment settings in place. Compare the new configuration examples with the active files before starting the services.</p><p>After health, sign-in, tasks, Wiki, search, and MCP all pass, switch <code>/opt/ershu/frontend/current</code>. Keep the previous release directory until acceptance is complete.</p><p>A database migration may prevent a package-only rollback. Confirm database compatibility and recovery procedures before upgrading.</p>`,49))])}const C=n(c,[["render",u]]);export{v as __pageData,C as default};
